const html = $input.item.json.data || '';

// Remove script/style blocks entirely, including their content
let text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

// Remove HTML comments
text = text.replace(/<!--[\s\S]*?-->/g, '');

// Strip remaining tags
text = text.replace(/<[^>]+>/g, ' ');

// Decode common entities
text = text.replace(/&nbsp;/g, ' ')
           .replace(/&amp;/g, '&')
           .replace(/&lt;/g, '<')
           .replace(/&gt;/g, '>')
           .replace(/&quot;/g, '"')
           .replace(/&#39;/g, "'");

// Collapse extra whitespace
text = text.replace(/\s+/g, ' ').trim();

// Truncate — keeps Groq token usage low and avoids irrelevant footer/nav junk
const cleanText = text.slice(0, 3000);

return {
  json: {
    cleanText: cleanText
  }
};

const data = $input.item.json.body || $input.item.json;
const lead = data.lead || {};

// Strip extension text, then strip everything except digits
function normalizePhone(raw) {
  const withoutExt = raw.split(/ext\.?/i)[0];
  let digits = withoutExt.replace(/\D/g, '');

  // Strip leading US country code so "1-555-123-4567" and "555-123-4567" match
  if (digits.length === 11 && digits.startsWith('1')) {
    digits = digits.slice(1);
  }

  return digits;
}

const rawPhones = (lead.contact && lead.contact.phones) || [];
const normalizedPhones = [...new Set(rawPhones.map(normalizePhone).filter(Boolean))];

const email = (lead.Email || lead.email || '').toLowerCase().trim();
const domain = ((lead.company && lead.company.domain) || '').toLowerCase().trim();

return {
  json: {
    fullName: lead.fullName || '',
    email: email,
    phones: normalizedPhones,
    primaryPhone: normalizedPhones[0] || null,
    companyName: (lead.company && lead.company.name) || '',
    domain: domain,
    tags: lead.tags || [],
    source: data.source || null,
    submittedAt: data.submittedAt || null
  }
};

const rawText = $input.item.json.text || '';

// Strip markdown code fences in case the model added them anyway
let cleaned = rawText.replace(/```json\s*/gi, '').replace(/```/g, '').trim();

let enrichment;
try {
  enrichment = JSON.parse(cleaned);
} catch (e) {
  // This throw is intentional — it's exactly what your future
  // Error Trigger / Dead Letter Queue sub-workflow will catch
  throw new Error(`Failed to parse LLM enrichment output: ${e.message}. Raw: ${cleaned}`);
}

return {
  json: {
    companySize: enrichment.companySize || 'Unknown',
    industry: enrichment.industry || 'Unknown',
    painPoint: enrichment.painPoint || 'Unknown'
  }
};

