INSERT INTO inbound_leads (
  email, full_name, primary_phone, company_name, domain, tags, source, submitted_at, enrichment, status
) VALUES (
  $1, $2, $3, $4, $5, $6::jsonb, $7, $8::timestamptz, $9::jsonb, 'enriched'
)
ON CONFLICT (email) DO NOTHING;
